    "tool": "workspace.read",
    "arguments": {
      "resource_id": "report.primary"
    },
    "claimed_grant_id": "grant.read"
  },
  "pre_action": {
    "effect_summary": "Read report.primary, making no modifications.",
    "claimed_grant_id": "grant.read",
    "scope_survives_without_story": true,
    "consequence_of_not_acting": "I would not know the current report contents and could not compare them to the check or repair accurately."
  }
}

